### Resolving relative paths to declaration files across modules

Source: https://github.com/microsoft/typescript/blob/v7.0.2/tests/baselines/reference/relativePathToDeclarationFile.errors.txt

Imports types and namespaces from declaration files using relative paths alongside external module requirements.

```typescript
    import foo = require('foo');
    import other = require('./other');
    import relMod = require('./sub/relMod');

    if(foo.M2.x){
    	var x = new relMod(other.M2.x.charCodeAt(0));
    }

```

```typescript
    export declare namespace M2 {
    	export var x: boolean;
    }

```

```typescript
    export declare namespace M2 {
    	export var x: string;
    }

```

```typescript
    declare class Test {
    	constructor(x: number);
    }
    export = Test;

```

