### Package.json exports resolution happens at compile-time only, not during emit

Source: https://github.com/microsoft/typescript/blob/main/tsc/internal/module/resolver.go

The `loadModuleFromExports` and `loadModuleFromTargetExportOrImport` functions handle package.json `exports` field resolution (subpath patterns, conditional exports like `import`/`require`/`node`, fallback arrays, null mappings). This is entirely a type-checking and module-resolution concern: it determines which .d.ts or .ts file to read for type information. The resolved file path is never substituted back into emitted import statements; the original import specifier text is preserved verbatim in the output.

```go
func (r *resolutionState) loadModuleFromExports(packageInfo *packagejson.InfoCacheEntry, ext extensions, subpath string) *resolved {
	if !packageInfo.Exists() || packageInfo.Contents.Exports.IsFalsy() {
		return continueSearching()
	}
	if subpath == "." {
		var mainExport packagejson.ExportsOrImports
		switch packageInfo.Contents.Exports.Type {
		case packagejson.JSONValueTypeString, packagejson.JSONValueTypeArray:
			mainExport = packageInfo.Contents.Exports
		case packagejson.JSONValueTypeObject:
			if packageInfo.Contents.Exports.IsConditions() {
				mainExport = packageInfo.Contents.Exports
			} else if dot, ok := packageInfo.Contents.Exports.AsObject().Get("."); ok {
				mainExport = dot
			}
		}
		if mainExport.Type != packagejson.JSONValueTypeNotPresent {
			return r.loadModuleFromTargetExportOrImport(ext, subpath, packageInfo, false, mainExport, "", false, ".")
		}
	} else if packageInfo.Contents.Exports.Type == packagejson.JSONValueTypeObject && packageInfo.Contents.Exports.IsSubpaths() {
		if result := r.loadModuleFromExportsOrImports(ext, subpath, packageInfo.Contents.Exports.AsObject(), packageInfo, false); !result.shouldContinueSearching() {
			return result
		}
	}
	return continueSearching()
}
```
